function fewestTokens(tokens, amount) {
    function fewest(remaining) {
        if (remaining === 0)
            return 0;
        let best = Infinity;
        for (const token of tokens)
            if (token <= remaining)
                best = Math.min(best, 1 + fewest(remaining - token));
        return best;
    }
    const result = fewest(amount);
    return result === Infinity ? -1 : result;
}

function fewestTokens(tokens, amount) {
    const fewest = new Array(amount + 1).fill(Infinity);
    fewest[0] = 0;
    for (let value = 1; value <= amount; value++) {
        for (const token of tokens) {
            if (token <= value && fewest[value - token] + 1 < fewest[value])
                fewest[value] = fewest[value - token] + 1;
        }
    }
    return fewest[amount] === Infinity ? -1 : fewest[amount];
}
